{
  "issue_summary": "The scoped Gurgaon store review found 2 late deliveries among 120 eligible orders. The measured late percentage is 1.66667%, below the approved 15% action threshold. Neither late order exceeded the defined packing, assignment-wait or travel thresholds. Available customer feedback describes limited, "
  ,"impact": {
    "rating": "Low",
    "rationale": "The customer linked to a confirmed late order said it had arrived and everything was fine. This supports limited inconvenience, not a blocked goal or serious harm. Consequences for the other late order are not documented; the rating reflects the available evidence, not proof that every customer was ",
    "evidence_refs": [
      "feedback:GG-03-FDBK-000001",
      "orders:GG-03-ORDR-000001",
      "observation:GG-03-ORD-00001",
      "observation:GG-03-ORD-00002"
    ]
  },
  "metric_claims": [
    {
      "key": "eligible_orders",
      "value": 120
    },
    {
      "key": "late_orders",
      "value": 2
    },
    {
      "key": "late_rate",
      "value": 0.016666666666666666
    },
    {
      "key": "late_long_packing",
      "value": 0
    },
    {
      "key": "late_long_assignment_wait",
      "value": 0
    }
  ],
  "findings": [
    {
      "id": "F1",
      "kind": "observation",
      "text": "The reliable scoped late percentage is below the policy threshold. Lateness remains measured against the original checkout promise.",
      "evidence_refs": [
        "metric:eligible_orders",
        "metric:late_orders",
        "metric:late_rate",
        "promise_history:GG-03-PRMS-000001",
        "orders:GG-03-ORDR-000001"
      ]
    },
    {
      "id": "F2",
      "kind": "observation",
      "text": "Both confirmed late orders had packing, post-packing assignment wait and travel durations below their respective long-stage thresholds. Both remain in the other-delay category; these classifications do not establish a cause. Assignment evidence is not applicable, rather than missing.",
      "evidence_refs": [
        "observation:GG-03-ORD-00001",
        "observation:GG-03-ORD-00002",
        "metric:late_other"
      ]
    },
    {
      "id": "F3",
      "kind": "report",
      "text": "The late-order customer reported arrival and said everything was fine. A separate customer's review reported on-time delivery with all items received. These are order-linked customer statements, not evidence of store-wide harm or satisfaction.",
      "evidence_refs": [
        "feedback:GG-03-FDBK-000001",
        "feedback:GG-03-FDBK-000002"
      ]
    }
  ],
  "alternatives": [
    {
      "explanation": "Time before packing or the overall promise budget may explain a miss despite short measured stages. The inspected timeline places packing start after order placement, but it does not establish why that interval occurred or a recurring process problem.",
      "support_refs": [
        "order_events:GG-03-EVNT-000001",
        "order_events:GG-03-EVNT-000002",
        "promise_history:GG-03-PRMS-000001"
      ],
      "counter_refs": [
        "observation:GG-03-ORD-00001",
        "observation:GG-03-ORD-00002"
      ],
      "gaps": [
        "The reason for the pre-packing interval is not established.",
        "The other late order has a retrieved stage observation but no inspected raw timeline explaining its miss."
      ]
    }
  ],
  "gaps": [
    "Customer consequences are documented for one late order, not the other. Missing feedback is not evidence of no harm.",
    "The evidence does not establish a root cause or justify staffing, dispatch or packing changes."
  ],
  "decision": "withhold_intervention",
  "withholding_reason": "Close without human work under the approved below-threshold policy: 1.66667% is below 15%, the denominator is supported, and retrieved observations show completed late deliveries. The available late-order report describes ordinary inconvenience with eventual receipt, with no credible serious-harm or blocked-goal report in the inspected evidence. The unexplained causes and undocumented consequence for the other late order remain limitations, not grounds for a redundant diagnostic task.",
  "recommendations": []
}
